#include <stdio.h>
#include <stdlib.h>

#define OUT_SIZE (1 << 20)

static char out[OUT_SIZE];
static size_t out_pos = 0;

static void write_char(char c) {
    if (out_pos == OUT_SIZE) {
        fwrite(out, 1, out_pos, stdout);
        out_pos = 0;
    }
    out[out_pos++] = c;
}

static void write_int(int x) {
    char digits[12];
    int count = 0;

    do {
        digits[count++] = (char)('0' + x % 10);
        x /= 10;
    } while (x > 0);

    while (count > 0)
        write_char(digits[--count]);
}

int main(void) {
    int N, M, P;
    if (scanf("%d %d %d", &N, &M, &P) != 3)
        return 0;

    int *rows = malloc((size_t)N * sizeof(int));
    int *cols = malloc((size_t)M * sizeof(int));

    for (int i = 0; i < N; i++)
        rows[i] = i;
    for (int j = 0; j < M; j++)
        cols[j] = j;

    for (int i = 0; i < P; i++) {
        char op;
        int a, b;
        scanf(" %c %d %d", &op, &a, &b);
        a--;
        b--;

        int *permutation = (op == 'L') ? rows : cols;
        int temp = permutation[a];
        permutation[a] = permutation[b];
        permutation[b] = temp;
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            write_int(rows[i] * M + cols[j] + 1);
            write_char(j + 1 == M ? '\n' : ' ');
        }
    }

    if (out_pos > 0)
        fwrite(out, 1, out_pos, stdout);

    free(rows);
    free(cols);
    return 0;
}
